// Expected: { lead_id }  — runs all checks against the latest pending
// messages for this lead.
const input = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};
if (headers['x-webhook-secret'] !== $vars.WEBHOOK_SECRET) {
  throw new Error('Unauthorized');
}
if (!input.lead_id) throw new Error('Missing: lead_id');
return [{ json: { lead_id: input.lead_id } }];

// Run quality gates. One report per message.
// Rules:
//   1. word_count_ok               body has fewer than 150 words
//   2. mentions_business           message contains the business name
//   3. mentions_pain_or_hook       message references the task or hook keyword
//   4. has_schema_link             schema URL is present in the body OR a separate schema_id is set
//   5. no_banned_phrases           none of the LLM/spam tells ("j'espère que…", "n'hésitez pas", "propulsé par AI", "Claude", "GPT", "n8n")
//   6. no_recent_contact           lead.last_contact_at < 60 days ago → fail
//   7. sector_match                diagnostic sector matches lead sector
//   8. cta_present                 contains a question mark and a 15min/quart d'heure mention

const rows = $input.first().json;
const messages = Array.isArray(rows) ? rows : [rows];
if (!messages.length) throw new Error('No pending messages found for lead');

const BANNED = [
  /j['']espère que ce message vous trouve/i,
  /n['']hésitez pas/i,
  /\bClaude\b/i, /\bGPT\b/i, /\bn8n\b/i, /\bSupabase\b/i, /\bManyChat\b/i,
  /propulsé par (l['']?)?\s?AI/i,
  /^[•\-*]\s/m  // bullet point at start of line
];

function wordCount(s) {
  return (s || '').trim().split(/\s+/).filter(Boolean).length;
}

const now = Date.now();
const SIXTY_DAYS = 60 * 24 * 3600 * 1000;

const results = messages.map(msg => {
  const lead = msg.consulting_leads || {};
  const diag = msg.consulting_diagnostics || {};
  const schema = msg.consulting_schemas || {};
  const body = msg.body || '';
  const diagJson = diag.raw_response || {};
  const task1 = (diagJson.tasks || [])[0] || {};

  const checks = {};
  checks.word_count_ok       = wordCount(body) < 150;
  checks.mentions_business   = lead.business_name ? body.toLowerCase().includes(lead.business_name.toLowerCase()) : false;
  checks.mentions_pain_or_hook = task1.name
    ? body.toLowerCase().includes(task1.name.toLowerCase().split(' ')[0])
    : Boolean(diagJson.pitch_hook);
  checks.has_schema_link     = Boolean(schema.public_url) && (msg.channel === 'instagram' || body.includes(schema.public_url) || body.toLowerCase().includes('schéma') || body.toLowerCase().includes('préparé'));
  checks.no_banned_phrases   = !BANNED.some(re => re.test(body));
  checks.no_recent_contact   = !lead.last_contact_at || (now - new Date(lead.last_contact_at).getTime() > SIXTY_DAYS);
  checks.sector_match        = !diagJson.sector || !lead.business_sector || diagJson.sector.toLowerCase().includes((lead.business_sector || '').toLowerCase().slice(0, 4));
  checks.cta_present         = /\?/.test(body) && /(15\s*min|quart\s*d['']heure|appel|échange)/i.test(body);

  const passed = Object.values(checks).every(Boolean);
  const failed = Object.entries(checks).filter(([k, v]) => !v).map(([k]) => k);

  return {
    json: {
      message_id: msg.id,
      lead_id: $('Validate input').first().json.lead_id,
      channel: msg.channel,
      checks,
      checker_passed: passed,
      failed_rules: failed,
      word_count: wordCount(body)
    }
  };
});

return results;

// Aggregate per-channel results.
const items = $input.all();
const all_passed = items.every(i => i.json.checker_passed);
const summary = items.map(i => ({
  channel: i.json.channel,
  passed: i.json.checker_passed,
  failed_rules: i.json.failed_rules
}));
return [{
  json: {
    lead_id: items[0].json.lead_id,
    all_passed,
    summary
  }
}];

